import { modals } from "@mantine/modals";
import type { ReactNode } from "react";

export type ConfirmOptions = {
  title?: ReactNode;
  message: ReactNode;
  confirmLabel?: string;
  cancelLabel?: string;
  /** Paints the confirm button red, for deletes and other destructive actions. */
  danger?: boolean;
};

/**
 * Ask the visitor to confirm an action. Resolves `true` on confirm and `false`
 * on cancel or when the modal is dismissed. Needs `DesignSystemProvider`.
 */
export function confirm(options: ConfirmOptions): Promise<boolean> {
  return new Promise((resolve) => {
    let settled = false;
    const settle = (value: boolean) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };
    modals.openConfirmModal({
      title: options.title ?? "Please confirm",
      children: options.message,
      labels: {
        confirm: options.confirmLabel ?? "Confirm",
        cancel: options.cancelLabel ?? "Cancel",
      },
      confirmProps: options.danger ? { color: "red" } : undefined,
      onConfirm: () => settle(true),
      onCancel: () => settle(false),
      onClose: () => settle(false),
    });
  });
}

import { useFormControl } from "@mongez/react-form";
import type { ControlProps } from "../types/control-props";

/** Explicit ids keep SSR, hydration, portal labels and repeated forms aligned. */
export function useControl(props: ControlProps, type = "text", multiple = false) {
  const control = useFormControl(
    { ...props, type, multiple },
    { multiple, isCollectable: type === "submit" ? () => false : undefined },
  );
  const error = props.error ?? control.error;
  const describedBy =
    [props.hint ? `${props.id}-hint` : "", error ? `${props.id}-error` : ""]
      .filter(Boolean)
      .join(" ") || undefined;
  const binding = {
    id: props.id,
    name: props.name,
    disabled: control.disabled,
    onBlur: control.onBlur,
    ref: (element: HTMLElement | null) => {
      control.inputRef.current = element;
      control.visibleElementRef.current = element;
    },
    "aria-invalid": Boolean(error),
    "aria-required": props.required || undefined,
    "aria-describedby": describedBy,
  };
  return { ...control, error, binding };
}

